import csv
from concurrent.futures import ProcessPoolExecutor, as_completed
import importlib
import json
import os
from pathlib import Path
import sys
import traceback

if os.environ.get('PYTHONHASHSEED') != '0':
    raise RuntimeError('PYTHONHASHSEED must equal 0')
repo = Path('/Volumes/移动硬盘（512G）/ReSETP')
runner_dir = repo / 'baselines/china_e3_e7'
sys.path.insert(0, str(runner_dir))
runner = importlib.import_module('run_t21_charging_timing_three_arms_20260805')
out = repo / 'docs/handoff/charging_timing_three_arms_run_20260805'
preflight = json.loads((out / 't25_resume_preflight.json').read_text(encoding='utf-8'))
if runner.protected_hashes() != preflight['protected_file_sha256_before']:
    raise RuntimeError('protected hashes differ from T25 preflight')
if (out / 't25_remaining_done.json').exists():
    raise RuntimeError('T25 completion marker already exists')

def csv_rows(name):
    with (out / name).open(encoding='utf-8', newline='') as handle:
        return list(csv.DictReader(handle))

raw_original = csv_rows('raw_runs.csv')
if len(raw_original) != 17:
    raise RuntimeError(f'expected exactly 17 materialized rows, found {len(raw_original)}')
original_by_key = {
    (row['instance_id'], row['arm'], int(row['seed'])): row
    for row in raw_original
}
if len(original_by_key) != 17:
    raise RuntimeError('existing materialized rows contain duplicate triples')
improvements = csv_rows('improvement_trace.csv')
slots = csv_rows('slot_distribution.csv')
mips = csv_rows('mip_timing_audit.csv')
witnesses = json.loads((out / 'solution_witnesses.json').read_text(encoding='utf-8'))['witnesses']
failures_existing = json.loads((out / 'failed_units.json').read_text(encoding='utf-8'))['failures']
if failures_existing:
    raise RuntimeError('pre-resume failed_units.json is not empty')
json_fields = {
    'violation_types_json',
    'completion_failure_classification_original_json',
    'last_persisted_state_json',
    'hgs_iterations_by_view_json',
    'hgs_iteration_limit_by_view_json',
    'last_improvement_by_view_json',
    'charging_start_times_json',
}
bool_fields = {
    'paper_claim_allowed', 'route_pool_mip_extended', 'unit_succeeded',
    'improvement_at_any_view_limit', 'improvement_at_total_iteration_limit',
}
def decode_run(row):
    item = dict(row)
    for field in json_fields:
        item[field] = json.loads(item[field])
    for field in bool_fields:
        item[field] = item[field] == 'True'
    return item

imp_by = {}
for row in improvements:
    imp_by.setdefault(row['task_id'], []).append(row)
slot_by = {}
for row in slots:
    slot_by.setdefault(row['task_id'], []).append(row)
mip_by = {row['task_id']: row for row in mips}
witness_by = {item['task']['task_id']: item for item in witnesses}
results = []
for row in raw_original:
    task_id = row['task_id']
    if task_id not in witness_by or task_id not in mip_by:
        raise RuntimeError(f'incomplete persisted evidence for {task_id}')
    results.append({
        'run': decode_run(row),
        'improvements': imp_by.get(task_id, []),
        'slots': slot_by.get(task_id, []),
        'mip': mip_by[task_id],
        'witness': witness_by[task_id],
        'failure': None,
    })
manifest = runner.full_manifest()
manifest_keys = {
    (item['instance_id'], item['arm'], int(item['seed']))
    for item in manifest
}
remaining = [
    item for item in manifest
    if (item['instance_id'], item['arm'], int(item['seed'])) not in original_by_key
]
if len(manifest) != 90 or len(manifest_keys) != 90 or len(remaining) != 73:
    raise RuntimeError('manifest/resume cardinality mismatch')
configuration = {
    'execution_mode': 'full',
    'iterations': dict(runner.DEFAULT_FULL_ITERATIONS),
    'checkpoints': dict(runner.REFERENCE_CHECKPOINTS),
    'archives': dict(runner.REFERENCE_ARCHIVES),
    'exact_elites': 8,
    'unit_state_dir': out / 'unit_states',
}
with ProcessPoolExecutor(max_workers=6) as pool:
    futures = {
        pool.submit(runner.run_one, spec, **configuration): spec
        for spec in remaining
    }
    for future in as_completed(futures):
        spec = futures[future]
        try:
            result = future.result()
        except Exception as exc:
            trace = traceback.format_exc()
            state = runner.read_unit_state(out / 'unit_states', spec)
            result = runner.failure_result(
                spec,
                execution_mode='full',
                state=state,
                exception_type=type(exc).__name__,
                exception_message=str(exc),
                traceback_text=trace,
            )
        results.append(result)
        runner.persist_batch_progress(out, results, expected_count=90)
        current = csv_rows('raw_runs.csv')
        current_by_key = {
            (row['instance_id'], row['arm'], int(row['seed'])): row
            for row in current
        }
        if any(current_by_key.get(key) != row for key, row in original_by_key.items()):
            raise RuntimeError('one or more of the 17 pre-existing result rows changed')
        print(
            f"DONE {result['run']['task_id']} {result['run']['terminal_status']} "
            f"MATERIALIZED={len(current)}/90",
            flush=True,
        )
final_rows = csv_rows('raw_runs.csv')
final_keys = {
    (row['instance_id'], row['arm'], int(row['seed']))
    for row in final_rows
}
if len(final_rows) != 90 or len(final_keys) != 90 or final_keys != manifest_keys:
    raise RuntimeError('final 90-unit materialization check failed')
final_by_key = {
    (row['instance_id'], row['arm'], int(row['seed'])): row
    for row in final_rows
}
if any(final_by_key.get(key) != row for key, row in original_by_key.items()):
    raise RuntimeError('pre-existing 17 result rows changed at completion')
after = runner.protected_hashes()
if after != preflight['protected_file_sha256_before']:
    raise RuntimeError('protected hashes changed during T25 resume')
failed = json.loads((out / 'failed_units.json').read_text(encoding='utf-8'))
runner.atomic_json(out / 't25_remaining_done.json', {
    'schema_version': 'resetp.t25-remaining-done.v1',
    'completed_at_utc': runner.utc_now(),
    'paper_claim_allowed': False,
    'preexisting_materialized_unit_count': 17,
    'newly_materialized_unit_count': 73,
    'total_materialized_unit_count': 90,
    'unique_triple_count': 90,
    'failed_unit_count': int(failed['failed_unit_count']),
    'preexisting_17_rows_unchanged': True,
    'protected_file_sha256_before': preflight['protected_file_sha256_before'],
    'protected_file_sha256_after': after,
    'protected_files_unchanged': True,
})
print('T25_REMAINING_73_MATERIALIZED', flush=True)
